// EntityServiceServer is the server API for EntityService service.
// All implementations must embed UnimplementedEntityServiceServer
// for forward compatibility.
//
// EntityService provides generic CRUD for entities and relationships managed
// by the agency's entitygraph DataManager. HTTP routes for each entity type
// (Goal, Workflow, ConfiguredRole, etc.) are generated from the agency schema
// by schemaroutes.RoutesFromSchema and wired to this service's methods.
// CodeValdCross injects type_id and name via ConstantBindings so a single
// generic RPC handles all entity types.
type EntityServiceServer interface {
	// ListEntities returns all entities of the type_id bound to this route.
	ListEntities(context.Context, *ListEntitiesRequest) (*ListEntitiesResponse, error)
	// CreateEntity creates a new entity with the type_id bound to this route.
	CreateEntity(context.Context, *CreateEntityRequest) (*EntityItem, error)
	// GetEntity retrieves a single entity by ID.
	GetEntity(context.Context, *GetEntityRequest) (*EntityItem, error)
	// UpdateEntity patches the properties of an existing entity.
	UpdateEntity(context.Context, *UpdateEntityRequest) (*EntityItem, error)
	// DeleteEntity soft-deletes an entity by ID.
	DeleteEntity(context.Context, *DeleteEntityRequest) (*DeleteEntityResponse, error)
	// ListRelationships returns all outbound edges of the relationship name
	// bound to this route from the given source entity.
	ListRelationships(context.Context, *ListRelationshipsRequest) (*ListRelationshipsResponse, error)
	// CreateRelationship creates a directed edge from entity_id to to_id.
	CreateRelationship(context.Context, *CreateRelationshipRequest) (*RelationshipItem, error)
	// DeleteRelationship removes a directed edge by its ID.
	DeleteRelationship(context.Context, *DeleteRelationshipRequest) (*DeleteRelationshipResponse, error)
	mustEmbedUnimplementedEntityServiceServer()
}

